import torch
from dataclasses import dataclass
from vllm.v1.attention.backend import (AttentionBackend, AttentionCGSupport,
    AttentionImpl, AttentionMetadata, AttentionMetadataBuilder, MultipleOf)
from vllm.v1.attention.backends.registry import AttentionBackendEnum, register_backend
from ref_impl import write_kv, paged_attention   # part 3

@dataclass
class RefMetadata(AttentionMetadata):
    qsl: list[int]              # query_start_loc
    seq_lens: list[int]
    block_table: torch.Tensor

class RefBuilder(AttentionMetadataBuilder[RefMetadata]):
    _cudagraph_support = AttentionCGSupport.NEVER  # uses Python lists
    reorder_batch_threshold = None                 # any order works

    def __init__(self, kv_cache_spec, layer_names, vllm_config, device):
        super().__init__(kv_cache_spec, layer_names, vllm_config, device)

    def build(self, common_prefix_len, m, fast_build=False):
        n = m.num_reqs           # common_prefix_len is always 0
        return RefMetadata(m.query_start_loc_cpu[:n + 1].tolist(),
                           m.seq_lens[:n].tolist(),
                           m.block_table_tensor[:n].long())

@register_backend(AttentionBackendEnum.CUSTOM)
class RefBackend(AttentionBackend):
    forward_includes_kv_cache_update = False   # cache write is a separate op
    @staticmethod
    def get_name(): return "CUSTOM"
    @staticmethod
    def get_impl_cls(): return RefImpl
    @staticmethod
    def get_builder_cls(): return RefBuilder
    @staticmethod
    def get_supported_kernel_block_sizes(kv_cache_spec=None):
        return [MultipleOf(16)]

class RefImpl(AttentionImpl[RefMetadata]):
    def __init__(self, num_heads, head_size, scale, num_kv_heads=None,
                 alibi_slopes=None, sliding_window=None, kv_cache_dtype="auto",
                 logits_soft_cap=None, attn_type="decoder",
                 kv_sharing_target_layer_name=None, **extra):
        assert sliding_window is None and kv_cache_dtype == "auto"
        self.num_heads, self.head_size, self.scale = num_heads, head_size, scale
        self.num_kv_heads = num_kv_heads or num_heads
        self.kv_cache_dtype = kv_cache_dtype

    def do_kv_cache_update(self, layer, key, value, kv_cache, slot_mapping):
        write_kv(key, value, kv_cache, slot_mapping.long(), self.head_size)

    def forward(self, layer, query, key, value, kv_cache, attn_metadata,
                output, output_scale=None, output_block_scale=None):
        if attn_metadata is None:                  # memory-profiling run
            return output.fill_(0)
        m = attn_metadata
        return paged_attention(query, kv_cache, m.qsl, m.seq_lens,
                               m.block_table, self.scale, self.head_size, output)
